import React, { useState, useEffect } from 'react';
import axios from 'axios';

// 🟢 වෙනම ෆයිල් වල තියෙන සියලුම මොඩියුලයන් මෙතනට Import කරගැනීම
import TeacherContent from './TeacherContent';
import TeacherQuiz from './TeacherQuiz';
import TeacherActivities from './TeacherActivities';
import ViewReports from './TeacherReports';
import TeacherQuestionBank from './TeacherQuestionBank'; // 🟢 NEW: ප්‍රධාන ප්‍රශ්න බැංකු මොඩියුලය Import කරන ලදි

const axiosInstance = axios;

export default function TeacherDashboard({ userName, userUsername, subject, qualifications, email, phone, address, handleLogout }) {
  const [activeTab, setActiveTab] = useState('dashboard');
  const [materials, setMaterials] = useState([]);
  const [timetable, setTimetable] = useState([]);
  const [isEditing, setIsEditing] = useState(false);
  const [preSelectedGrade, setPreSelectedGrade] = useState(null);

  const fullSubject = subject || 'Grade 8 - Mathematics'; 
  const subjectParts = fullSubject.split(' - ');
  const teachingSubject = subjectParts.length > 1 ? subjectParts[1] : fullSubject;

  // ගුරුවරයාට අදාළ ශ්‍රේණි ලැයිස්තුව ඩයිනමික්ව සකසා ගැනීම
  const teacherGrades = Array.isArray(timetable) ? [...new Set(timetable.map(c => c.grade))] : [];
  const uniqueAssignedGrades = teacherGrades.length > 0 ? teacherGrades.join(', ') : 'Not Assigned Yet';

  const [profileData, setProfileData] = useState({ name: userName, username: userUsername, qualifications, email, phone, address, password: '' });

  // 🟢 FIXED: backend සර්වර් පෝට් එක 8081 ලෙස සක්‍රීය කරන ලදි
  const fetchData = () => {
    axiosInstance.get('http://localhost:8081/api/learning-materials').then(res => setMaterials(Array.isArray(res.data) ? res.data : []));
    axiosInstance.get('http://localhost:8081/api/timetable').then(res => setTimetable(Array.isArray(res.data) ? res.data.filter(c => c.teacher === userName) : []));
  };

  useEffect(() => { fetchData(); }, [userName]);

  const handleProfileUpdate = () => {
    if (!profileData.username.trim()) { alert("❌ Error: Username cannot be empty!"); return; }
    axiosInstance.post('http://localhost:8082/api/update-teacher-credentials', {
        currentUsername: userUsername, newUsername: profileData.username, newPassword: profileData.password || 'Teacher@123'
    }).then(res => {
        if (res.data.status === "Success") { alert("✅ Credentials updated successfully! Logging out..."); handleLogout(); }
    });
    setIsEditing(false);
  };

  // 🎯 වෙනම තියෙන ෆයිල් ටික ටැබ්ස් අනුව ලස්සනට රෙන්ඩර් කරන කොටස
  const renderContent = () => {
    switch (activeTab) {
      case 'dashboard':
        return (
          <div>
            <div style={{ backgroundColor: '#15803d', padding: '30px', borderRadius: '15px', color: 'white', marginBottom: '30px' }}>
              <h1>Welcome back, {profileData.name}! 👋</h1>
              <p>System operational for target assigned structures: <strong>{uniqueAssignedGrades} ({teachingSubject})</strong></p>
            </div>
            <div style={{ display: 'grid', gridTemplateColumns: 'repeat(auto-fit, minmax(200px, 1fr))', gap: '20px', marginBottom: '30px' }}>
              <DashboardCard title="Active Subject" count={teachingSubject} icon="📚" textColor="#3b82f6" />
              <DashboardCard title="Assigned Grades" count={uniqueAssignedGrades} icon="🏫" textColor="#7c3aed" />
              <DashboardCard title="Total Resources" count={materials.filter(m => m.subject === teachingSubject).length} icon="📂" textColor="#eab308" />
            </div>
            <h3>🏫 Active Scheduled Timetable Mapping</h3>
            <p style={{ color: '#64748b', fontSize: '13px', marginTop: '-5px', marginBottom: '15px' }}>💡 Quick Action: Click any card below to instantly open Content Manager targeted for that grade.</p>
            <div style={{ display: 'grid', gridTemplateColumns: 'repeat(auto-fill, minmax(280px, 1fr))', gap: '20px' }}>
                {timetable.map(c => (
                  <div key={c.id} onClick={() => { setPreSelectedGrade(c.grade); setActiveTab('upload'); }} style={{ backgroundColor: 'white', padding: '20px', borderRadius: '12px', borderTop: '5px solid #15803d', cursor: 'pointer', boxShadow: '0 4px 15px rgba(0,0,0,0.02)', transition: '0.2s' }} onMouseOver={e => e.currentTarget.style.transform='translateY(-3px)'} onMouseOut={e => e.currentTarget.style.transform='translateY(0)'}>
                    <div style={{ fontWeight: 'bold', color: '#1e293b' }}>{c.grade} - {c.subject}</div>
                    <div style={{ fontSize: '13px', color: '#64748b', marginTop: '6px' }}>🕒 {c.day} ({c.time_slot})</div>
                  </div>
                ))}
            </div>
          </div>
        );

      case 'upload': 
        return <TeacherContent userName={userName} teachingSubject={teachingSubject} materials={materials} fetchData={fetchData} timetable={timetable} preSelectedGrade={preSelectedGrade} setPreSelectedGrade={setPreSelectedGrade} teacherGrades={teacherGrades} />;
      
      case 'quiz': 
        // 🟢 FIXED: teacherGrades සහ timetable පාස් කරන ලදි (ඩේටාබේස් එකෙන් Grades/Subjects නිවැරදිව ෆිල්ටර් වීමට)
        return <TeacherQuiz userName={userName} subject={fullSubject} qualifications={qualifications} teacherGrades={teacherGrades} timetable={timetable} />;
      
      case 'questionbank':
        // 🟢 NEW: මධ්‍යගත ප්‍රශ්න බැංකු (Question Bank) පිටුව මෙතනට ලින්ක් කරන ලදි
        return <TeacherQuestionBank userName={userName} teacherGrades={teacherGrades} timetable={timetable} />;

      case 'activities':
        return <TeacherActivities timetable={timetable} teachingSubject={teachingSubject} userName={userName} />;

      case 'reports': 
        return <ViewReports subject={fullSubject} />;
        
      case 'profile':
        return (
          <div style={{ animation: 'fadeIn 0.5s' }}>
            <h2>👤 My Profile Settings</h2>
            <div style={{ backgroundColor: 'white', padding: '35px', borderRadius: '15px', maxWidth: '500px' }}>
                <div style={{ display: 'flex', justifyContent: 'space-between', marginBottom: '20px' }}>
                  <h3>Profile Records</h3>
                  {!isEditing ? <button onClick={() => setIsEditing(true)} style={styles.editProfileBtn}>✏️ Edit Profile</button> : <button onClick={handleProfileUpdate} style={styles.saveProfileBtn}>💾 Save Changes</button>}
                </div>
                <div style={{ display: 'flex', flexDirection: 'column', gap: '15px' }}>
                  <div><label style={styles.label}>Full Name</label><input type="text" value={profileData.name} onChange={e => setProfileData({...profileData, name: e.target.value})} disabled={!isEditing} style={styles.inputStyleProfile(isEditing)} /></div>
                  <div><label style={styles.label}>LMS Username *</label><input type="text" value={profileData.username} onChange={e => setProfileData({...profileData, username: e.target.value})} disabled={!isEditing} style={styles.inputStyleProfile(isEditing)} /></div>
                  <div><label style={styles.label}>New Security Password</label><input type="password" placeholder="Type new password to change..." value={profileData.password} onChange={e => setProfileData({...profileData, password: e.target.value})} disabled={!isEditing} style={styles.inputStyleProfile(isEditing)} /></div>
                </div>
            </div>
          </div>
        );
      default: return null;
    }
  };

  return (
    <div style={{ display: 'flex', height: '100vh', overflow: 'hidden', backgroundColor: '#f8fafc', fontFamily: 'sans-serif', width: '100%' }}>
      {/* Sidebar UI Navigation Section */}
      <div style={{ width: '260px', backgroundColor: '#145c2e', color: 'white', padding: '30px 0', display: 'flex', flexDirection: 'column', flexShrink: 0 }}>
        <div style={{ padding: '0 25px', marginBottom: '40px', textAlign: 'center' }}>
            <h2 style={{ margin: 0, fontSize: '24px' }}>Aura Pen Saku</h2>
            <p style={{ color: '#86efac', margin: '5px 0 0 0', fontSize: '12px', fontWeight: 'bold' }}>TEACHER DASHBOARD</p>
        </div>
        <div style={{ display: 'flex', flexDirection: 'column', gap: '5px', padding: '0 15px', overflowY: 'auto' }}>
          <SidebarBtn active={activeTab === 'dashboard'} onClick={() => setActiveTab('dashboard')} icon="🏠" text="Dashboard Overview" />
          <SidebarBtn active={activeTab === 'upload'} onClick={() => setActiveTab('upload')} icon="📤" text="Content Manager" />
          <SidebarBtn active={activeTab === 'quiz'} onClick={() => setActiveTab('quiz')} icon="📝" text="Quiz & Exam Manager" />
          
          {/* 🟢 NEW SIDEBAR BUTTON: මධ්‍යගත ප්‍රශ්න බැංකු බොත්තම ඇතුළත් කිරීම */}
          <SidebarBtn active={activeTab === 'questionbank'} onClick={() => setActiveTab('questionbank')} icon="📚" text="Question Bank" />
          
          <SidebarBtn active={activeTab === 'activities'} onClick={() => setActiveTab('activities')} icon="🧩" text="Manage Activities" />
          <SidebarBtn active={activeTab === 'reports'} onClick={() => setActiveTab('reports')} icon="📈" text="View Reports" />
          <SidebarBtn active={activeTab === 'profile'} onClick={() => setActiveTab('profile')} icon="👤" text="My Profile Settings" />
        </div>
        <div style={{ marginTop: 'auto', padding: '20px 15px 0 15px' }}><button onClick={handleLogout} style={styles.logoutBtn}>🚪 Logout Portal</button></div>
      </div>
      {/* Main Content Render Core Area */}
      <div style={{ flex: 1, padding: '40px 50px', overflowY: 'auto' }}>{renderContent()}</div>
    </div>
  );
}

// Reusable Sub-Interface Layout Cards
const SidebarBtn = ({ active, onClick, icon, text }) => (
  <button onClick={onClick} style={{ width: '100%', textAlign: 'left', padding: '14px 20px', backgroundColor: active ? 'rgba(255,255,255,0.15)' : 'transparent', color: 'white', border: 'none', borderRadius: '10px', cursor: 'pointer', fontSize: '14px', display: 'flex', alignItems: 'center', gap: '15px', fontWeight: active ? 'bold' : 'normal', transition: '0.2s' }}>
    <span style={{ fontSize: '18px' }}>{icon}</span> {text}
  </button>
);

const DashboardCard = ({ title, count, icon, textColor }) => (
  <div style={{ backgroundColor: 'white', padding: '25px', borderRadius: '15px', display: 'flex', justifyContent: 'space-between', alignItems: 'center', borderLeft: `5px solid ${textColor}`, boxShadow: '0 4px 15px rgba(0,0,0,0.02)' }}>
    <div><p style={{ margin: 0, color: '#64748b', fontSize: '13px', fontWeight: 'bold' }}>{title}</p><h2 style={{ fontSize: '18px', whiteSpace: 'normal', wordBreak: 'break-word', marginTop: '5px' }}>{count}</h2></div>
    <div style={{ fontSize: '28px' }}>{icon}</div>
  </div>
);

const styles = {
  label: { display: 'block', marginBottom: '6px', color: '#475569', fontSize: '13px', fontWeight: 'bold' },
  fullInput: { width: '100%', padding: '12px', borderRadius: '8px', border: '1px solid #cbd5e1', backgroundColor: '#f8fafc', outline: 'none', boxSizing: 'border-box', fontSize: '14px' },
  logoutBtn: { width: '100%', padding: '12px', backgroundColor: '#dc2626', color: 'white', border: 'none', borderRadius: '8px', fontWeight: 'bold', cursor: 'pointer', fontSize: '15px' },
  editProfileBtn: { padding: '6px 14px', backgroundColor: '#f0fdf4', color: '#15803d', border: '1px solid #bbf7d0', borderRadius: '6px', cursor: 'pointer', fontWeight: 'bold', fontSize: '12px' },
  saveProfileBtn: { padding: '6px 14px', backgroundColor: '#15803d', color: 'white', border: 'none', borderRadius: '8px', cursor: 'pointer', fontWeight: 'bold', fontSize: '12px' },
  inputStyleProfile: (isEditing) => ({ width: '100%', padding: '12px', borderRadius: '8px', border: isEditing ? '1px solid #3b82f6' : '1px solid #cbd5e1', backgroundColor: isEditing ? 'white' : '#f8fafc', outline: 'none', boxSizing: 'border-box', color: '#1e293b', fontSize: '14px' })
};
